// This code has been fully generated by an AI.

// Package sport groups FIT sports into the categories used by filters,
// statistics and the heatmap, and provides German display labels.
package sport

// Category is a user-facing group of sports.
type Category struct {
	ID    string
	Label string
	Icon  string
	// Sports lists the FIT sport names belonging to the category. The
	// category "other" has none and matches everything not listed elsewhere.
	Sports []string
	// Color is used for the category on maps.
	Color string
}

// Other is the ID of the catch-all category.
const Other = "other"

// Categories in display order.
var Categories = []Category{
	{ID: "bike", Label: "Rad", Icon: "🚴", Sports: []string{"cycling", "e_biking"}, Color: "#e8590c"},
	{ID: "run", Label: "Laufen", Icon: "🏃", Sports: []string{"running"}, Color: "#7048e8"},
	{ID: "hike", Label: "Wandern & Gehen", Icon: "🥾", Sports: []string{"hiking", "walking"}, Color: "#2b8a3e"},
	{ID: Other, Label: "Sonstige", Icon: "⏱️", Color: "#1c7ed6"},
}

// ByID returns the category with the given ID.
func ByID(id string) (Category, bool) {
	for _, c := range Categories {
		if c.ID == id {
			return c, true
		}
	}
	return Category{}, false
}

// CategoryOf returns the category of a FIT sport.
func CategoryOf(sport string) Category {
	for _, c := range Categories {
		for _, s := range c.Sports {
			if s == sport {
				return c
			}
		}
	}
	c, _ := ByID(Other)
	return c
}

// KnownSports returns all sports assigned to a named category; used to
// express the "other" category as "none of these".
func KnownSports() []string {
	var out []string
	for _, c := range Categories {
		out = append(out, c.Sports...)
	}
	return out
}

// labels maps FIT sport/sub-sport names to German labels. Sub-sport entries
// take precedence; unknown values fall back to the sport label.
var labels = map[string]string{
	"cycling":                  "Radfahren",
	"cycling/road":             "Rennrad",
	"cycling/gravel_cycling":   "Gravel",
	"cycling/mountain":         "MTB",
	"cycling/downhill":         "MTB",
	"cycling/cyclocross":       "Cyclocross",
	"cycling/commuting":        "Pendeln",
	"cycling/e_bike_fitness":   "E-Bike",
	"cycling/e_bike_mountain":  "E-MTB",
	"cycling/indoor_cycling":   "Indoor",
	"cycling/virtual_activity": "Indoor (virtuell)",
	"e_biking":                 "E-Bike",
	"running":                  "Laufen",
	"running/trail":            "Trailrun",
	"running/treadmill":        "Laufband",
	"hiking":                   "Wandern",
	"walking":                  "Gehen",
	"swimming":                 "Schwimmen",
	"multisport":               "Multisport",
	"training":                 "Training",
}

// Label returns the German label of a sport/sub-sport combination.
func Label(sport, subSport string) string {
	if l, ok := labels[sport+"/"+subSport]; ok {
		return l
	}
	if l, ok := labels[sport]; ok {
		return l
	}
	if sport == "" {
		return "Unbekannt"
	}
	return sport
}

// Icon returns the emoji of the sport's category.
func Icon(sport string) string { return CategoryOf(sport).Icon }
